// Extract params from webhook body: topicSlug, rangeStart (ISO timestamp), feeds (array of URLs).
// Defaults: no topic, 7-day range, empty feeds (caller must provide feeds).
const item = $input.first();
const raw = item?.json || {};

// Resolve the request body robustly across n8n webhook output shapes:
// 1. raw.body  — n8n webhook v2 standard (parsed JSON object or JSON string)
// 2. raw.data  — some proxy / middleware wrappings
// 3. raw.payload — alternative wrapper key
// 4. raw itself — if it already contains the expected keys at the root
function resolveBody(r) {
  function tryParse(v) {
    if (v && typeof v === 'object') return v;
    if (typeof v === 'string' && v.trim().startsWith('{')) {
      try { return JSON.parse(v); } catch {}
    }
    return null;
  }
  const fromBody = tryParse(r.body);
  if (fromBody) return fromBody;
  const fromData = tryParse(r.data);
  if (fromData && (fromData.feeds !== undefined || fromData.topicSlug !== undefined || fromData.range !== undefined)) return fromData;
  const fromPayload = tryParse(r.payload);
  if (fromPayload) return fromPayload;
  // Fall back to raw root if it looks like the expected shape
  if (r.feeds !== undefined || r.topicSlug !== undefined || r.range !== undefined) return r;
  return r;
}

const body = resolveBody(raw);
const topicSlug = (body.topicSlug ?? '').toString().trim();
const range = (body.range || '1w').toString().toLowerCase().trim();
let feeds = body.feeds || [];
if (!Array.isArray(feeds)) feeds = [];

// Compute rangeStart from body or derive from range
let rangeStart = body.rangeStart || '';
if (!rangeStart) {
  let days = 7;
  if (range === '2w') days = 14;
  else if (range === '1d') days = 1;
  else if (range === '3d') days = 3;
  else if (range === '5m') { const d = new Date(); d.setMinutes(d.getMinutes() - 5); rangeStart = d.toISOString(); }
  else if (range === '30m') { const d = new Date(); d.setMinutes(d.getMinutes() - 30); rangeStart = d.toISOString(); }
  else if (range === '1h') { const d = new Date(); d.setHours(d.getHours() - 1); rangeStart = d.toISOString(); }
  if (!rangeStart) {
    const d = new Date();
    d.setDate(d.getDate() - days);
    rangeStart = d.toISOString();
  }
}

// Resolve topicId: look up by slug if set
let topicId = body.topicId ?? null;

return [{ json: { topicSlug, topicId, range, rangeStart, feeds } }];

// Emit one item per feed URL so the RSS reader processes each feed.
const params = $input.first().json;
const feeds = params.feeds || [];
if (feeds.length === 0) {
  return [{ json: { feedUrl: '', _skip: true, _params: params } }];
}
return feeds.map(url => ({ json: { feedUrl: url, _params: params } }));

function extractSourceName(url) {
  const SOURCE_MAP = {
    'techcrunch.com': 'TechCrunch',
    'arstechnica.com': 'Ars Technica',
    'theverge.com': 'The Verge',
    'reuters.com': 'Reuters',
    'bbc.com': 'BBC',
    'bbc.co.uk': 'BBC',
    'cnn.com': 'CNN',
    'aljazeera.com': 'Al Jazeera',
    'apnews.com': 'AP News'
  };
  for (const [domain, name] of Object.entries(SOURCE_MAP)) {
    if (url.includes(domain)) return name;
  }
  try { return new URL(url).hostname; } catch { return 'Unknown'; }
}

function stripHtml(text) {
  if (!text) return '';
  return text.replace(/<[^>]*>/g, ' ').replace(/&[^;]+;/g, ' ').replace(/\s+/g, ' ').trim();
}

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  if (data._skip) continue;
  const url = (data.link || data.guid || '').trim();
  if (!url) continue;

  let publishedAt = data.isoDate || data.pubDate || new Date().toISOString();
  try {
    const d = new Date(publishedAt);
    publishedAt = Number.isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
  } catch { publishedAt = new Date().toISOString(); }

  const category = (data.categories && data.categories.length > 0)
    ? (typeof data.categories[0] === 'string' ? data.categories[0] : (data.categories[0].name || data.categories[0]._ || 'general')).toLowerCase().trim()
    : 'general';

  results.push({
    json: {
      title: (data.title || 'Untitled').trim(),
      url,
      source: extractSourceName(url),
      published_at: publishedAt,
      category,
      summary: stripHtml(data.contentSnippet || data.summary || '').slice(0, 500) || null,
      content: stripHtml(data['content:encoded'] || data.content || '') || null
    }
  });
}

if (results.length === 0) {
  return [{ json: { _empty: true } }];
}
return results;

// Ensure Fetch Recent Articles runs exactly once (not once per inserted article).
const items = $input.all();
return items.length ? [items[0]] : [{ json: {} }];

// Build digest markdown — same format as workflow 02.
const params = $('Normalize Pipeline Params').first().json;
const topicSlug = params.topicSlug || '';
const range = params.range || '1w';
const rangeStart = new Date(params.rangeStart);
const endDate = new Date();
const rangeLabels = { '5m': 'Last 5 minutes', '30m': 'Last 30 minutes', '1h': 'Last 1 hour', '1d': 'Last 1 day', '3d': 'Last 3 days', '1w': 'Last 1 week', '2w': 'Last 2 weeks' };
const rangeLabel = rangeLabels[range] || 'Last 1 week';
const articles = $input.all().map(i => i.json).filter(a => a.id || a.title);

function formatDate(date) {
  return new Date(date).toLocaleDateString('en-US', {
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
  });
}

function formatDateShort(date) {
  return new Date(date).toLocaleDateString('en-US', {
    month: 'short', day: 'numeric', year: 'numeric'
  });
}

function topicDisplay(slug) {
  if (!slug) return '';
  return slug.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
}

const startDate = rangeStart;
const lines = [];
const titleParts = ['\u{1F4F0} AI News Weekly Digest', topicSlug ? topicDisplay(topicSlug) : null, rangeLabel].filter(Boolean);
lines.push('# ' + titleParts.join(' \u2014 '));
lines.push('');
lines.push(`**${formatDate(startDate)} \u2014 ${formatDate(endDate)}**`);
lines.push('');
const uniqueSources = new Set(articles.map(a => a.source));
lines.push(`> ${articles.length} articles from ${uniqueSources.size} sources`);
lines.push('');
lines.push('---');
lines.push('');

if (articles.length === 0) {
  lines.push('_No articles found for this period._');
} else {
  const grouped = {};
  for (const a of articles) {
    const cat = a.category || 'general';
    if (!grouped[cat]) grouped[cat] = [];
    grouped[cat].push(a);
  }
  const sortedCategories = Object.entries(grouped).sort((a, b) => b[1].length - a[1].length);
  for (const [category, catArticles] of sortedCategories) {
    const displayCat = category.charAt(0).toUpperCase() + category.slice(1);
    lines.push(`## ${displayCat} (${catArticles.length})`);
    lines.push('');
    catArticles.sort((a, b) => new Date(b.published_at) - new Date(a.published_at));
    for (const a of catArticles) {
      const date = a.published_at ? formatDateShort(a.published_at) : 'Date N/A';
      const summary = a.summary ? (a.summary.slice(0, 200) + (a.summary.length > 200 ? '...' : '')) : '_No summary available._';
      lines.push(`### [${a.title}](${a.url})`);
      lines.push('');
      lines.push(`\u{1F4C5} ${date} \u00B7 \u{1F4E1} ${a.source}`);
      lines.push('');
      lines.push(summary);
      lines.push('');
    }
    lines.push('---');
    lines.push('');
  }
}
lines.push(`_Generated on ${formatDate(new Date())} by AI News Digest._`);

const markdown = lines.join('\n');

return [{
  json: {
    ingested: articles.length,
    indexed: 0,
    digest: { articleCount: articles.length, markdown }
  }
}];
